html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font: 14px/1.45 \"Segoe UI\", system-ui, -apple-system, sans-serif;
}

#view {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100vh;
  display: block;
  cursor: crosshair;
}

#panel {
  position: fixed;
  top: 16px;
  left: 16px;
  width: 264px;
  max-height: calc(100vh - 32px);
  overflow-y: auto;
  padding: 16px;
  background: var(--panel);
  border: 1px solid var(--edge);
  border-radius: 14px;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.5);
  transition: transform 0.25s ease, opacity 0.25s ease;
}

#panel.hidden {
  transform: translateX(-120%);
  opacity: 0;
  pointer-events: none;
}

#panel h1 {
  margin: 0 0 2px;
  font-size: 20px;
  letter-spacing: 0.5px;
  background: linear-gradient(90deg, var(--accent), var(--accent2));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

#panel .sub {
  margin: 0 0 12px;
  font-size: 12px;
  color: var(--dim);
}

#panel section {
  border-top: 1px solid var(--edge);
  padding: 10px 0 12px;
}

#panel h2 {
  margin: 0 0 8px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--dim);
}

label {
  display: block;
  margin: 8px 0;
  font-size: 13px;
}

output {
  float: right;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

input[type=\"range\"] {
  width: 100%;
  margin-top: 4px;
  accent-color: var(--accent);
  cursor: pointer;
}

input[type=\"text\"] {
  flex: 1;
  min-width: 0;
  padding: 7px 10px;
  background: rgba(0, 0, 0, 0.35);
  border: 1px solid var(--edge);
  border-radius: 8px;
  color: var(--text);
  font-family: ui-monospace, \"Cascadia Mono\", Consolas, monospace;
  font-size: 12px;
}

input[type=\"text\"]:focus {
  outline: none;
  border-color: var(--accent);
}

button {
  padding: 7px 12px;
  background: rgba(76, 194, 255, 0.12);
  border: 1px solid rgba(76, 194, 255, 0.35);
  border-radius: 8px;
  color: var(--text);
  font-size: 13px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
}

button:hover { background: rgba(76, 194, 255, 0.25); }
button:active { transform: scale(0.96); }

.row {
  display: flex;
  gap: 8px;
  align-items: center;
}

.row button { flex: 0 0 auto; }

.seed-row { margin-bottom: 4px; }

.stats {
  margin: 8px 0 0;
  font-size: 12px;
  color: var(--dim);
  font-variant-numeric: tabular-nums;
}

#panel footer {
  display: flex;
  align-items: center;
  gap: 10px;
  border-top: 1px solid var(--edge);
  padding-top: 10px;
}

#panel footer .hint {
  margin: 0;
  font-size: 11px;
  color: var(--dim);
}

#collapse { padding: 4px 10px; }

#expand {
  position: fixed;
  top: 16px;
  left: 16px;
  z-index: 5;
  font-size: 16px;
  padding: 8px 12px;
  background: var(--panel);
  border: 1px solid var(--edge);
  backdrop-filter: blur(10px);
}

#expand.hidden { display: none; }

@media (max-width: 640px) {
  #panel { width: calc(100vw - 32px); }
}
